const cmd = `$d='D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts\\_ov2_cc\\topics'
Get-ChildItem $d -Filter *.json | ForEach-Object {
  $j = Get-Content $_.FullName -Raw | ConvertFrom-Json
  Write-Output ("##### TOPIC " + $j.id + " :: " + $j.title + "  (" + $j.posts_count + " posts, created " + $j.created_at + ")")
  foreach($p in $j.post_stream.posts){
    $t = $p.cooked -replace '<[^>]+>',' ' -replace '\\s+',' '
    Write-Output ("  【" + $p.username + " " + $p.created_at.Substring(0,10) + "】" + $t)
  }
  Write-Output ""
}`;
const r = await tools.pwsh({ description: "Dump CC topic posts", command: cmd });
console.log(r.kind === 'foreground' ? r.stdout.text.slice(0,14000) : JSON.stringify(r));
